// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address[] calldata governables, bool[] calldata isGoverned) public {
        vm.assume(governables.length > 0);
        vm.assume(governables.length == isGoverned.length);

        // Ensure at least one true bool in isGoverned
        bool hasTrue = false;
        for (uint i = 0; i < isGoverned.length; i++) {
            if (isGoverned[i]) {
                hasTrue = true;
                break;
            }
        }
        vm.assume(hasTrue);

        // Call setGoverned — in reference it updates mapping, in mutant it does nothing
        c.setGoverned(governables, isGoverned);

        // After the call, at least one address should be governed (true) if the reference worked
        bool anyGoverned = false;
        for (uint i = 0; i < governables.length; i++) {
            if (isGoverned[i] && c.governed(governables[i])) {
                anyGoverned = true;
                break;
            }
        }
        assertTrue(anyGoverned);
    }
}

